  "coach.reader.capsule.title": "التشغيل",
  "coach.reader.capsule.body": "تشغيل وإيقاف، والسهمان للمقطع السابق والتالي. الضغط المتكرر بسرعة يتخطّى مقاطع أكثر.",
  "coach.reader.tabs.title": "أدوات القراءة",
