  // المساعدة (Help)
  "help.title": "كيف أستخدم التطبيق؟",
  "help.replayTour": "إعادة الجولة التعريفية",
  "help.new.title": "الجديد في هذا التحديث",
  "help.new.summary": "الملخّص الشامل: للصفحة أو للوحدة كاملة. يختار الطالب أسلوبه لكل كتاب (الالتزام بالكتاب أو التوسّع بأمثلة وتمارين). يحل تمارين نهاية الوحدة بلون مختلف، ويشرح دراسة الحالة بتبسيط، ويرتّب دروس اللغات في جداول. ويمكن إعادة صياغته أو حذفه، ويظهر نطاق الصفحات التي يغطيها.",
  "help.new.video": "ملخّص الفيديو: مشاهد متحركة وراوٍ يشرح، وأسئلة سريعة بين المشاهد، ثم «ابدأ الاختبار». يظهر مدته، ويعمل بملء الشاشة، ويُحفظ للمشاهدة بلا إنترنت.",
  "help.new.cards": "البطاقات بأربعة أنواع: معاني كلمات (مع صورة توضيحية للمشتركين)، تعاريف، أسئلة وأجوبة، مقارنات — مع طباعتها PDF.",
  "help.new.toc": "فهرس الكتاب في القارئ: فصول الكتاب أو وحدات المنهج بصفحاتها، والانتقال السريع بين الوحدات.",
  "help.new.audio": "حفظ صوت الكتاب كله على الجهاز من صفحة الكتاب («الصوت المحفوظ»): يكمل من حيث وقف، ويصل إشعار عند الاكتمال.",
  "help.new.counters": "عدّادات واضحة للطلبات الذكية وصفحات الاستماع في القارئ والملخّص والفيديو وصفحة الحساب.",
  "help.usage.title": "الطلبات الذكية والصفحات: كيف تُحسب؟",
  "help.usage.ai": "الطلب الذكي هو كل مرة يكتب فيها الذكاء الاصطناعي شيئًا جديدًا: ملخّص، اختبار، مجموعة بطاقات، خريطة ذهنية، عرض تقديمي، ترجمة، سؤال، منهج، أو ملخّص فيديو.",
  "help.usage.aiCount": "المحتوى القصير طلب واحد. والملخّص الطويل للوحدة يُكتب أجزاءً (الجزء نحو ٦–٧ صفحات)، فيُحسب طلبًا لكل جزء. وملخّص الفيديو يُحسب كذلك لكل جزء من مشاهده، ويحتاج ملخّص الوحدة أولًا إن لم يكن جاهزًا. وإعادة الصياغة أو التوليد تُحسب من جديد.",
  "help.usage.free": "ما يُحفظ لا يُحسب مرة ثانية: فتح ملخّص أو فيديو أو خريطة جاهزة مجاني، ومعنى الكلمة والنطق الدقيق لا يُحسبان من الطلبات.",
  "help.usage.pages": "صفحات الاستماع: الصفحة تُحسب مرة واحدة في الشهر عند الاستماع لها، وإعادة الاستماع لها مجانية. وحفظ صوت الكتاب يُحسب بنفس الطريقة لكل صفحة تُحفظ.",
  "help.usage.where": "الطلبات والصفحات المتبقية تظهر في عدّادات القارئ والملخّص والفيديو، وفي صفحة الحساب.",
  "help.topic.library.title": "المكتبة",
  "help.topic.library.body": "الضغط على الكتاب يفتحه للقراءة. والضغط المطوّل يكشف الخيارات: المجلدات، المنهج الدراسي، إعادة التسمية، الأرشفة، والحذف.",
  "help.topic.longPress.title": "الضغط المطوّل",
  "help.topic.longPress.body": "في المكتبة، الضغط المطوّل على أي كتاب يفتح قائمة إجراءات إضافية مهمة. مفتاح لاكتشاف ميزات أكثر.",
  "help.topic.syllabus.title": "المنهج الدراسي",
  "help.topic.syllabus.body": "وحدات بقائمة متابعة، ولكل وحدة ملخّص شامل وملخّص فيديو واختبار وخريطة ذهنية، و«ملف المذاكرة» يجمع ملخّصات الوحدات كلها في PDF واحد.",
  "help.topic.audio.title": "القراءة الصوتية",
  "help.topic.audio.body": "قارئ يقرأ ويشرح بصوت طبيعي. التحكّم بالسرعة (حتى ×0.5)، والتنقّل بين المقاطع — والضغط المتكرر يسرّع التخطّي (×2 ×3).",
  "help.topic.pronounce.title": "النطق والترجمة",
  "help.topic.pronounce.body": "نطق دقيق بالتشكيل، وترجمة فورية، وأصوات بعدة لغات.",
  "help.topic.ai.title": "أدوات الذكاء",
  "help.topic.ai.body": "ملخّص شامل للصفحة أو الوحدة أو الكتاب كله، اختبارات، بطاقات مراجعة بأنواعها، خريطة ذهنية، عرض تقديمي، وملخّص فيديو — من أدوات الدراسة في القارئ أو من صفحة المنهج.",
  "help.topic.focus.title": "التركيز والمتابعة",
  "help.topic.focus.body": "مؤقّت تركيز (بومودورو)، سلسلة أيام، ودرجات لوضع التركيز تخفّف المشتّتات أثناء القراءة.",
  "help.contact.design": "تصميم وتطوير: Nahla",
  "help.contact.mail": "للتواصل والملاحظات: Nahlah@Nahlah.io",
  "help.madeIn": "إحدى مشاريع Nahla.tech",
