  // الجولة التعريفية (How-to tour)
  "howto.step0.title": "المكتبة",
  "howto.step0.body": "كل الكتب هنا. الضغط على الكتاب يفتحه للقراءة مباشرة. والضغط المطوّل على الكتاب يفتح قائمة الخيارات: نقل لمجلد، المنهج الدراسي، إعادة تسمية، أرشفة، وحذف.",
  "howto.step1.title": "الضغط المطوّل",
  "howto.step1.body": "في المكتبة، الضغط المطوّل على أي كتاب يكشف إجراءات إضافية مهمة (المجلدات والمنهج والأرشفة). تجربته تكشف المزيد.",
  "howto.step2.title": "المنهج الدراسي",
  "howto.step2.body": "لكل كتاب منهج بوحدات وقائمة متابعة، مع اختبار وخريطة ذهنية وملخّص صوتي لكل وحدة. يُفتح من قائمة الضغط المطوّل على الكتاب.",
  "howto.step3.title": "القراءة الصوتية",
  "howto.step3.body": "قارئ بصوت طبيعي يقرأ ويشرح. التحكّم بالسرعة، والتنقّل بين المقاطع، والاستئناف من نفس الموضع.",
  "howto.step4.title": "النطق والترجمة",
  "howto.step4.body": "نطق دقيق بالتشكيل، وترجمة فورية، وأصوات بعدة لغات — حسب الحاجة.",
  "howto.step5.title": "أدوات الذكاء",
  "howto.step5.body": "تلخيص الصفحة، الأسئلة، بطاقات المراجعة، الخريطة الذهنية، والعرض التقديمي — كلها بضغطة.",
  "howto.skip": "تخطّي",
  "howto.start": "يلّا نبدأ",
