  "coach.cmd.action.title": "Quick commands",
  "coach.cmd.action.body": "Shortcuts to what you use most: add a book, plan and schedule, focus session and more.",
  "coach.cmd.mic.title": "Voice assistant",
  "coach.cmd.mic.body": "Ask by talking, like “summary of unit one” or “quiz me on chapter two”.",
  "coach.book.cta.title": "Listen",
  "coach.book.cta.body": "Starts the book or continues from the last page you reached.",
  "coach.book.seg.title": "Book page sections",
  "coach.book.seg.body": "Three sections: Units is the book's table of contents, Tools has every tool including the syllabus, and Saved holds your files, the notes page and what you saved from the reader.",
  "coach.book.unit.title": "Units = table of contents",
  "coach.book.unit.body": "Tap any unit to open the book at its first page.",
  "coach.book.create.title": "Create the syllabus",
