  "coach.reader.page.title": "The page",
  "coach.reader.page.body": "The sentence being read is highlighted on the page itself.",
  "coach.reader.page.double": "Double-tap any line: reading starts there",
  "coach.reader.page.swipe": "Swipe left or right: turn pages",
  "coach.reader.page.hold": "Press and hold a word: save it to My words",
  "coach.reader.nav.title": "Moving between pages",
  "coach.reader.nav.body": "Tap the page number to jump straight to a printed book page; drag the bar next to it to scrub.",
  "coach.reader.capsule.title": "Playback",
  "coach.reader.capsule.body": "Play and pause; the arrows go to the previous and next segment. Quick repeated taps skip further.",
  "coach.reader.tabs.title": "Reading tools",
  "coach.reader.tabs.body": "Three groups: Listen (speed, sleep, walk, music, voice, translate), Study (assistant, Ask your book, bookmarks) and View. A tool's options appear right below it.",
  "coach.reader.toggle.title": "Hide the tools",
  "coach.reader.toggle.body": "For more reading space. Tap again to bring them back; your choice is remembered.",
  "coach.fc.seg.title": "Review hub",
