  "coach.fc.words.title": "My words",
  "coach.fc.words.body": "Words saved in the reader with their meanings, ready to turn into cards or a file.",
  "coach.fc.gen.title": "Generate study material",
  "coach.fc.gen.body": "New cards, a summary or a quiz — pick the book, part and count.",
