  "help.title": "How do I use the app?",
  "help.replayTour": "Replay the intro tour",
  "help.new.title": "New in this update",
  "help.new.summary": "Full summary: for a page or a whole unit. Each book gets a chosen style (stick to the book, or expand with examples and exercises). End-of-unit exercises are solved in a different color, case studies are explained simply, and language lessons go into tables. Summaries can be rewritten or deleted, and show the pages they cover.",
  "help.new.video": "Video summary: animated scenes with a narrator, quick checks between scenes, then \"Start the quiz\". Shows its length, plays full screen, and is saved for offline viewing.",
  "help.new.cards": "Four card types: word meanings (with an illustration for subscribers), definitions, Q&A, and comparisons — printable as PDF.",
  "help.new.toc": "Book contents in the reader: chapters or syllabus units with their pages, and quick jumps between units.",
  "help.new.audio": "Save the whole book's audio from the book page (\"Audio saved on this device\"): resumes where it stopped and notifies when done.",
  "help.new.counters": "Clear counters for AI requests and listening pages in the reader, summary, video and account page.",
  "help.usage.title": "AI requests and pages: how are they counted?",
  "help.usage.ai": "An AI request is each time the AI writes something new: a summary, quiz, set of cards, mind map, presentation, translation, question, syllabus, or video summary.",
  "help.usage.aiCount": "Short content is one request. A long unit summary is written in parts (about 6–7 pages each), one request per part. A video summary is counted the same way per part of its scenes, and needs the unit summary first if it isn't ready. Rewriting or regenerating counts again.",
  "help.usage.free": "Saved content isn't counted again: opening a ready summary, video or map is free, and word meanings and precise pronunciation don't count as requests.",
  "help.usage.pages": "Listening pages: a page counts once per month when listened to, and re-listening is free. Saving a book's audio counts the same way for each saved page.",
  "help.usage.where": "Remaining requests and pages appear in the counters in the reader, summary, video, and account page.",
  "help.topic.library.title": "Library",
  "help.topic.library.body": "Tapping a book opens it for reading. A long press reveals options: folders, study syllabus, rename, archive, and delete.",
  "help.topic.longPress.title": "Long press",
  "help.topic.longPress.body": "In the library, long-pressing any book opens an important extra-actions menu. Key to discovering more features.",
  "help.topic.syllabus.title": "Study syllabus",
  "help.topic.syllabus.body": "Units with a checklist, each with a quiz, mind map, and audio summary. You can also print the syllabus or the map.",
  "help.topic.audio.title": "Audio reading",
  "help.topic.audio.body": "A reader that reads and explains in a natural voice. Control the speed (down to ×0.5) and move between segments — repeated taps speed up skipping (×2 ×3).",
  "help.topic.pronounce.title": "Pronunciation & translation",
  "help.topic.pronounce.body": "Precise pronunciation with diacritics, instant translation, and voices in several languages.",
  "help.topic.ai.title": "AI tools",
  "help.topic.ai.body": "Page summary, questions, review cards, mind map, and presentation — all in one tap.",
  "help.topic.focus.title": "Focus & tracking",
  "help.topic.focus.body": "A focus timer (Pomodoro), day streaks, and focus-mode levels that reduce distractions while reading.",
  "help.contact.design": "Designed & developed by: Nahla",
  "help.contact.mail": "Contact & feedback: Nahlah@Nahlah.io",
  "help.madeIn": "A Nahla.tech project",
